"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { useParams, usePathname, useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { Fragment, useState, type FormEvent, type ReactNode } from "react";
import { Button, buttonVariants } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { AddPicker, EmptyPane, ErrorNote, FieldRow, FormRow, ListSkeleton, NameChips, Pagination, Pane, PaneHeader, PaneSkeleton, splitList, text } from "../ui";

type Row = Outputs["genres"]["list"]["data"][number];
type Detail = Outputs["genres"]["get"];
type Input<K extends keyof Inputs["genres"]> = Inputs["genres"][K];

const PAGE_SIZE = 20;
const KEY = ["genres"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

const GENRES_FIELDS = ["name"] as const;
type GenresField = (typeof GENRES_FIELDS)[number];

type GenresValues = {
  name: string;
};

const EMPTY_GENRES: GenresValues = {
  name: ""
};

const GENRES_CREATE: readonly GenresField[] = ["name"];

function toGenresCreateInput(v: GenresValues): Input<"create"> {
  return {
    name: v.name
  };
}

type GenresSetter = <K extends keyof GenresValues>(key: K, value: GenresValues[K]) => void;

function renderGenresField(field: GenresField, values: GenresValues, set: GenresSetter) {
  switch (field) {
    case "name":
      return (
      <FormRow label="Name" htmlFor="name">
        <Input id="name" type="text" maxLength={60} value={values.name} onChange={e => set("name", e.target.value)} required />
      </FormRow>
      );
  }
}

function GenresForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly GenresField[];
  initial: GenresValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: GenresValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<GenresValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: GenresSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderGenresField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

export function GenresLayout({ children }: { children: ReactNode }) {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["genres"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.genres.list(input) });
  const pathname = usePathname();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Genres" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/genres/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New genre">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No genres yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    href={`/genres/${text(row.id)}`}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", pathname === `/genres/${text(row.id)}` && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.name) || "Genre " + text(row.id)}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        {children}
      </section>
    </div>
  );
}

export function GenresIndex() {
  return <EmptyPane>Select a genre from the list, or create one.</EmptyPane>;
}

export function GenresNew() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.genres.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/genres/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New genre">
      <GenresForm
        fields={GENRES_CREATE}
        initial={EMPTY_GENRES}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toGenresCreateInput(values))}
      />
    </Pane>
  );
}

/**
 * The tracks of a genre: the Track rows TrackGenre links it to. Changes go
 * through track_genres, under its own rules; the names come with the row.
 */
function GenresTracksField({ row, user }: { row: Detail; user: SessionUser | null }) {
  void user;
  const queryClient = useQueryClient();
  const linkInput = { genre_id: row.id, page_size: 200 } as Inputs["track_genres"]["list"];
  const links = useQuery({ queryKey: ["track_genres", "list", linkInput], queryFn: () => client.track_genres.list(linkInput) });
  const options = useQuery({ queryKey: ["tracks", "list", { page_size: 200 }], queryFn: () => client.tracks.list({ page_size: 200 }) });
  const settle = async () => {
    await queryClient.invalidateQueries({ queryKey: ["track_genres"] });
    await queryClient.invalidateQueries({ queryKey: KEY });
  };
  void settle;
  const add = useMutation({ mutationFn: (input: Inputs["track_genres"]["create"]) => client.track_genres.create(input), onSuccess: settle });
  const remove = useMutation({ mutationFn: (input: Inputs["track_genres"]["delete"]) => client.track_genres.delete(input), onSuccess: settle });
  type Link = Outputs["track_genres"]["list"]["data"][number];
  const far = new Map(row.tracks.map(item => [text(item.id), item] as const));
  const label = (link: Link) => text(far.get(text(link.track_id))?.title);
  const items = [...(links.data?.data ?? [])].sort((a, b) => label(a).localeCompare(label(b)));
  const busy = add.isPending || remove.isPending;
  return (
    <div>
      {links.data ? <NameChips items={items} keyOf={link => text(link.id)} label={label} onRemove={user !== null ? link => remove.mutate({ id: link.id }) : undefined} busy={busy} /> : <NameChips items={row.tracks} keyOf={item => text(item.id)} label={item => text(item.title)} />}
      {user !== null ? (
        <AddPicker
          options={(options.data?.data ?? []).filter(item => !far.has(text(item.id)))}
          keyOf={item => text(item.id)}
          label={item => text(item.title)}
          placeholder="Add a track…"
          onAdd={item => add.mutate({ genre_id: row.id, track_id: item.id } as Inputs["track_genres"]["create"])}
          busy={busy}
        />
      ) : null}
      <ErrorNote error={add.error ?? remove.error} className="mt-2" />
    </div>
  );
}

export function GenresDetail() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const queryClient = useQueryClient();
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.genres.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.name) || "Genre " + text(row.id)}
    >


      <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Tracks">
          <GenresTracksField row={row} user={user} />
        </FieldRow>
      </dl>
    </Pane>
  );
}
